/// <summary>
/// MPJ_15465_DirectDebitAutomation
/// </summary>
class METCustPaymJournalAutomation extends RunBaseBatch
{
    container                               allParameters;  // This is the only structure packed

    METCustPaymJournalAutomationParamsTmp   journalAutomationParams;
    container                               paymProposalParams;
    container                               generatePaymentParams;
    container                               fileFormatParams;

    LedgerJournalTable                      journalTable;

    #define.CurrentVersion(7)

    #localmacro.CurrentList
        allParameters
    #endmacro

}

Method.Source:
    /// <summary>
    /// Extract parameters from packed container.
    /// </summary>   
    public void unpackAllParameters()
    {
        container journalAutomationParamsCon;

        [journalAutomationParamsCon,
         paymProposalParams,
         generatePaymentParams,
         fileFormatParams] = allParameters;

        journalAutomationParams = con2Buf(journalAutomationParamsCon);
    }

/// <summary>
/// getJournalAutomationParams
/// </summary>
/// <returns>journalAutomationParams</returns>
public METCustPaymJournalAutomationParamsTmp getJournalAutomationParams()
{
    return journalAutomationParams.data();
}

/// <summary>
/// setJournalAutomationParams
/// </summary>
/// <param name = "_journalAutomationParams">_journalAutomationParams</param>
public void setJournalAutomationParams(METCustPaymJournalAutomationParamsTmp _journalAutomationParams)
{
    journalAutomationParams.data(_journalAutomationParams);
}

/// <summary>
/// parmPaymProposalParams
/// </summary>
/// <param name = "_paymProposalParams">_paymProposalParams</param>
/// <returns>paymProposalParams</returns>
public container parmPaymProposalParams(container _paymProposalParams = paymProposalParams)
{
    paymProposalParams = _paymProposalParams;
    return paymProposalParams;
}

/// <summary>
/// parmGeneratePaymentParams
/// </summary>
/// <param name = "_generatePaymentParams">_generatePaymentParams</param>
/// <returns>generatePaymentParams</returns>
public container parmGeneratePaymentParams(container _generatePaymentParams = generatePaymentParams)
{
    generatePaymentParams = _generatePaymentParams;
    return generatePaymentParams;
}

/// <summary>
/// parmFileFormatParams
/// </summary>
/// <param name = "_fileFormatParams">_fileFormatParams</param>
/// <returns>fileFormatParams</returns>
public container parmFileFormatParams(container _fileFormatParams = fileFormatParams)
{
    fileFormatParams = _fileFormatParams;
    return fileFormatParams;
}

    /// <summary>
    /// run
    /// </summary>
    public void run()
    {
        setPrefix("@MET:AutomatedDirectDebitProcess");
       
        ttsbegin;

        this.createJournalHeader();
        this.generatePaymentProposal();
        if(journalTable.numOfLines())
        {
            this.updateLinesAfterPaymentProposal();
            if(journalAutomationParams.GeneratePayment)
            {
                if(!Global::isRunningOnBatch())
                    ttscommit;  // call to generatePayments may produce UI prompt when running interactive

                this.generatePayments();

                if(!Global::isRunningOnBatch())
                    ttsbegin;  // see note above about prompt resulting from call to generatePayments. Reinstate transaction.
            }
            this.postJournal();
            if(journalTable.Posted)
            {
                this.generateDepositSlip();
            }
        }
        else
        {
            info("@MET:NoMatchingLinesFound");
        }

        ttscommit;   
    }

/// <summary>
/// Construct instance of CustSumForPaym based on packed parameters
/// </summary>
/// <returns>CustSumForPaym</returns>
public CustSumForPaym getCustSumForPaymFromPackedParams()
{
    if(conLen(generatePaymentParams))
    {
        CustSumForPaym sumForPaym = new CustSumForPaym();
        sumForPaym.parmLedgerJournalId(journalTable.JournalNum);
        sumForPaym.metParmAutomationJournalId(journalTable.JournalNum);
        sumForPaym.metParmFromAutomation(true);
        sumForPaym.unpack(generatePaymentParams);
        return sumForPaym;
    }
    else
    {
        throw error("@MET:PaymProposalParamsNotDefined");
    }
}

    /// <summary>
    /// Perform any updates after GL journal lines have been created by payment proposal.
    /// </summary>
    protected void updateLinesAfterPaymentProposal()
    {
        setPrefix("@MET:UpdatingJournalLines");

        LedgerJournalTrans  journalTrans;

        while select forupdate journalTrans
            where   journalTrans.JournalNum == journalTable.JournalNum
        {
            journalTrans.BankDepositVoucher = journalAutomationParams.UseDepositSlip;   
            journalTrans.PaymReference = '-';      // **** TODO from where?   
               
            if(!journalTrans.PaymSpec && journalTrans.PaymMode)
            {
                CustPaymModeSpec paymSpec;
                select firstonly paymSpec
                    where   paymSpec.PaymMode == journalTrans.PaymMode;
                journalTrans.PaymSpec = paymSpec.Specification;
            }

            journalTrans.update();
        }
    }

    /// <summary>
    /// Generate deposit slip.
    /// </summary>
    protected void generateDepositSlip()
    {
        setPrefix("@MET:GeneratingDepositSlip");

        if(!journalAutomationParams.UseDepositSlip)
        {
            return;
        }

        LedgerJournalTrans journalTrans;
        select firstonly journalTrans
            where   journalTrans.JournalNum == journalTable.JournalNum;

        BankDepositSlip depositSlip = BankDepositSlip::metConstruct(journalTrans);
        depositSlip.metParmPostingDate(journalAutomationParams.DepositSlipPostingDate);
        depositSlip.metParmFromAutomation(true);
        if(!depositSlip.metParmPostingDate())
        {
            depositSlip.metParmPostingDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));;
        }

        depositSlip.metParmLedgerJournalID(journalTable.JournalNum);
        depositSlip.run();

        info("@MET:BankDepositPosted");
    }

    /// <summary>
    /// Post journal
    /// </summary>
    protected void postJournal()
    {
        if(!journalAutomationParams.PostJournal)
        {
            return;
        }

        setPrefix("@MET:PostingJournal");
        var post = LedgerJournalCheckPost::newLedgerJournalTable(journalTable, true);
        post.run();  
          
        info(strFmt("@MET:JournalHasBeenPosted", journalTable.JournalNum));
        journalTable.reread();
    }

    /// <summary>
    /// Create GL journal header.
    /// </summary>
    protected void createJournalHeader()
    {
        setPrefix("@MET:CreatingJournalHeader");

        journalTable.initValue();
        journalTable.initFromLedgerJournalName(journalAutomationParams.LedgerJournalNameId);
        journalTable.JournalNum   = JournalTableData::newTable(journalTable).nextJournalId();
        journalTable.Name         = journalAutomationParams.Description;
        journalTable.insert();

        journalTable.selectForUpdate(true);

        info(strFmt("@MET:JournalCreated",
            journalTable.JournalNum,
            journalTable.Name));
    }

/// <summary>
/// caption
/// </summary>
/// <returns>caption</returns>
public ClassDescription caption()
{
    return "@MET:AutomatedDirectDebitProcess";
}

    /// <summary>
    /// Generate payments 
    /// </summary>
    protected void generatePayments()
    {
        setPrefix("@MET:GeneratingPayments");

        if(conLen(generatePaymentParams))
        {            
            CustSumForPaym sumForPaym = this.getCustSumForPaymFromPackedParams();
            // ** Export format

            Args paymentArgs = new Args();
            LedgerJournalTrans journalTrans;
            select firstonly journalTrans
                where   journalTrans.JournalNum == journalTable.JournalNum;
            paymentArgs.record(journalTrans);
            paymentArgs.parmEnumType(enumnum(UserInteractive));
            paymentArgs.parmEnum(UserInteractive::No);
            sumForPaym.parmArgs(paymentArgs);            
            sumForPaym.metParmfromAutomation(true);
            sumForPaym.metParmPackedFileFormatParams(fileFormatParams);
            sumForPaym.run();
        }
        else
        {
            warning("@MET:GeneratePaymentParamsNotDefined");
        }
    }

    /// <summary>
    /// Run payment proposal
    /// </summary>
    protected void generatePaymentProposal()
    {
        setPrefix("@MET:GeneratingPaymentProposalLines");

        CustVendCreatePaymJournal_Cust createPaymJournal = CustVendCreatePaymJournal_Cust::construct();

        if(conLen(paymProposalParams))
        {
            // Generate
            createPaymJournal.unpack(paymProposalParams);
            createPaymJournal.metsetGetLastCalled(true);
            if(!createPaymJournal.parmDefaultOffsetAccount())
            {
                if(journalTable.OffsetAccountType == LedgerJournalACType::Bank)
                {
                    createPaymJournal.parmDefaultOffsetAccountType(LedgerJournalACTypeForPaymProposal::Bank);
                    createPaymJournal.parmDefaultOffsetLedgerDimension(journalTable.OffsetLedgerDimension);
                }                   
            }
            createPaymJournal.metparmLedgerJournalId(journalTable.JournalNum);
            createPaymJournal.parmInBatch(this.isInBatch());
            createPaymJournal.parmSkipProposalEditForm(true);
            QueryRun qr = createPaymJournal.queryRun();
            
            if(!createPaymJournal.parmToDate())
            {
                createPaymJournal.parmToDate(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
            }

            createPaymJournal.runOperation();

            // Transfer
            CustVendPaymProposalTransferToJournal transfer = CustVendPaymProposalTransferToJournal::constructForPaymProposal(createPaymJournal.paymProposal());
            transfer.transferProposal();  
                         
            journalTable.reread();

            if(journalTable.numOfLines())
            {
                info(strFmt("@MET:NumLinesCreatedForPaymProposal", journalTable.numOfLines()));
            }
            else               
            {
                warning("@MET:NoMatchingLinesPaymentProposal");
            }
        }
        else
        {
            warning("@MET:PaymProposalParamsNotDefined");
        }
    }

    public boolean validate(object _calledFrom = null)
    {
        boolean ret = super(_calledFrom);

        if(!journalAutomationParams.LedgerJournalNameId)
        {
            ret = checkFailed("@MET:JournalNameNotSpecified");
        }        
        if(!conLen(this.paymProposalParams))
        {
            ret = checkFailed("@MET:PaymProposalParamsNotSpecified");
        }        
        return ret;
    }

protected boolean canRunInNewSession()
{
    return false;
}

public Object dialog()
{        
    DialogRunBase dlg = Dialog::newFormnameRunBase(formStr(METCustPaymJournalAutomation), this);
    dlg = this.dialogInternal(dlg);        
    return dlg;            
}

protected void dialogPost(Object dialog)
{
    super(dialog);
    //this.batchInfo().fieldBatchExecuteValue(true);
}

public boolean getFromDialog()
{
    boolean ret = super();
    return ret;
}

public container pack()
{
    allParameters = [
         buf2Con(journalAutomationParams),
         paymProposalParams,
         generatePaymentParams,
         fileFormatParams
    ];
    return [#CurrentVersion, #CurrentList];
}

public boolean unpack(container _packedClass)
{
    boolean ret;   
    Version     version = RunBase::getVersion(_packedClass);
    switch (version)
    {
        case #CurrentVersion:           
            [version, #CurrentList] = _packedClass;           
            ret = true;
            break;
        default:           
            ret = false;
            break;
    }
    if(ret)
    {
        this.unpackAllParameters();
    }
    return ret;
}

public static void main(Args args)
{
    METCustPaymJournalAutomation p = new METCustPaymJournalAutomation();
    if(p.prompt())
    {
        p.runOperation();
    }
}
